function profile_upload(string $field,int $userId): ?string {
    if(!isset($_FILES[$field])||$_FILES[$field]['error']===UPLOAD_ERR_NO_FILE)return null;
    $file=$_FILES[$field];if($file['error']!==UPLOAD_ERR_OK||$file['size']>5*1024*1024)throw new RuntimeException('Chaque image doit peser au maximum 5 Mo.');
    $mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)throw new RuntimeException('Formats acceptés : JPG, PNG ou WebP.');
    $dir=__DIR__.'/../../../public/uploads/profiles';if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('Impossible de préparer le dossier des photos.');$name=$userId.'-'.$field.'-'.bin2hex(random_bytes(12)).'.'.$ext;if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Impossible d’enregistrer la photo.');return 'uploads/profiles/'.$name;
}
if($_SERVER['REQUEST_METHOD']==='POST'){
