            if($first===''||$last===''||mb_strlen($first)>255||mb_strlen($last)>255||mb_strlen($bio)>255||mb_strlen($address)>255||mb_strlen($postalCode)>20||mb_strlen($city)>120||mb_strlen($country)>120||mb_strlen($phone)>30)throw new RuntimeException('Vérifie les champs et leur longueur.');
            if($phone!==''&&!preg_match('/^[0-9+().\-\s]{6,30}$/',$phone))throw new RuntimeException('Saisis un numéro de téléphone valide.');
            if(!$hasCoverImage&&isset($_FILES['cover'])&&$_FILES['cover']['error']!==UPLOAD_ERR_NO_FILE)throw new RuntimeException('La base doit contenir la colonne cover_image. Mets à jour Users depuis src/database/schema.sql.');
            if((!$hasPostalCode&&$postalCode!=='')||(!$hasPhone&&$phone!=='')||(!$hasCity&&$city!=='')||(!$hasCountry&&$country!==''))throw new RuntimeException('La base Users doit contenir postal_code, city, country et phone. Mets à jour src/database/schema.sql.');
            $avatar=profile_upload('avatar',(int)$user['Id_users']);$cover=$hasCoverImage?profile_upload('cover',(int)$user['Id_users']):null;$sql='UPDATE Users SET first_name=:first,name=:name,biographie=:bio,adresse=:address';$params=['first'=>$first,'name'=>$last,'bio'=>$bio,'address'=>$address,'id'=>$user['Id_users']];if($hasPostalCode){$sql.=',postal_code=:postal_code';$params['postal_code']=$postalCode;}if($hasCity){$sql.=',city=:city';$params['city']=$city;}if($hasCountry){$sql.=',country=:country';$params['country']=$country;}if($hasPhone){$sql.=',phone=:phone';$params['phone']=$phone;}if($avatar!==null){$sql.=',avatar=:avatar';$params['avatar']=$avatar;}if($cover!==null){$sql.=',cover_image=:cover';$params['cover']=$cover;}$sql.=' WHERE Id_users=:id';$pdo->prepare($sql)->execute($params);$notice='Ton profil a été mis à jour.';
