        }
    }catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Une erreur est survenue lors de la sauvegarde.';if(!($e instanceof RuntimeException))error_log($e->__toString());}
}
$profileFields='Id_users,first_name,name,email,adresse,biographie,avatar,created_at'.($hasCoverImage?',cover_image':'').($hasPostalCode?',postal_code':'').($hasCity?',city':'').($hasCountry?',country':'').($hasPhone?',phone':'');$q=$pdo->prepare('SELECT '.$profileFields.' FROM Users WHERE Id_users=:id');$q->execute(['id'=>$user['Id_users']]);$profile=$q->fetch();$profile['cover_image']=$profile['cover_image']??null;$profile['postal_code']=$profile['postal_code']??'';$profile['city']=$profile['city']??'';$profile['country']=$profile['country']??'';$profile['phone']=$profile['phone']??'';
