lass="flex items-center gap-2 font-semibold text-slate-800"><i data-lucide="user-round" class="h-4 w-4 text-teal-700"></i>Photo de profil</span><small class="mt-1 block text-slate-500">JPG, PNG ou WebP · 5 Mo max.</small><input id="avatarUpload" name="avatar" type="file" accept="image/jpeg,image/png,image/webp" class="mt-3 block w-full text-xs text-slate-500"></label><label class="cursor-pointer rounded-xl border border-dashed border-slate-300 p-4 text-sm hover:border-teal-500"><span class="flex items-center gap-2 font-semibold text-slate-800"><i data-lucide="image" class="h-4 w-4 text-teal-700"></i>Image de fond</span><small class="mt-1 block text-slate-500">JPG, PNG ou WebP · 5 Mo max.</small><input id="coverUpload" name="cover" type="file" accept="image/jpeg,image/png,image/webp" class="mt-3 block w-full text-xs text-slate-500"></label></div><div class="flex justify-end gap-3 border-t border-slate-100 pt-4"><button type="button" id="cancelProfileModal" class="rounded-lg border border-slate-200 px-4 py-2.5 text-sm">Annuler</button><button class="rounded-lg bg-teal-700 px-5 py-2.5 text-sm font-semibold text-white hover:bg-teal-800">Enregistrer les modifications</button></div></form></div></div>
<script>
(()=>{const modal=document.getElementById('profileModal');function open(focus){modal.classList.remove('hidden');modal.classList.add('flex');if(focus==='avatar')setTimeout(()=>document.getElementById('avatarUpload').focus(),80);if(focus==='cover')setTimeout(()=>document.getElementById('coverUpload').focus(),80)}function close(){modal.classList.add('hidden');modal.classList.remove('flex')}<?php if($error&&($_POST['action']??'')==='profile-save'): ?>open('');<?php endif; ?>document.querySelectorAll('[data-open-profile]').forEach(button=>button.addEventListener('click',()=>open(button.dataset.openProfile)));document.getElementById('closeProfileModal').addEventListener('click',close);document.getElementById('cancelProfileModal').addEventListener('click',close);modal.addEventListener('click',event=>{if(event.target===modal)close()});document.addEventListener('keydown',event=>{if(event.key==='Escape')close()});document.querySelectorAll('[data-tab]').forEach(tab=>tab.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(item=>item.setAttribute('aria-selected',String(item===tab)));document.querySelectorAll('.profile-tab-panel').forEach(panel=>{const active=panel.id===tab.getAttribute('aria-controls');panel.hidden=!active;panel.classList.toggle('hidden',!active)})}));if(window.lucide)lucide.createIcons()})();
</script>
